/*
 * A324470  Partial sums of ternary tribonacci word A092782.
 * https://oeis.org/A324470
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 64, u16 n <= 64, u32 n <= 64, u64 n <= 64, u128 n <= 64,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = Σ_{i=1}^{n} (t_i + 1)
 * where (t_i) is the ternary tribonacci word over {0,1,2} generated by
 * the morphism 0 → 01, 1 → 02, 2 → 0, starting from the seed 0.
 * The function memoises the word digits and returns the partial sum.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* 0 → 01, 1 → 02, 2 → 0   (seed 0) */
    static uint8_t *word = NULL;   /* cached word digits 0,1,2 */
    static size_t   len  = 0;      /* current length of cached word */

    /* grow the cached word until it has at least n digits */
    if (n > len) {
        if (!word) {
            word = (uint8_t *)malloc(1);
            word[0] = 0;               /* seed */
            len  = 1;
        }
        while (len < n) {
            size_t old = len;
            /* compute length of next word */
            size_t newlen = 0;
            for (size_t i = 0; i < old; ++i) {
                if (word[i] == 0 || word[i] == 1)
                    newlen += 2;
                else
                    newlen += 1;        /* word[i] == 2 */
            }
            uint8_t *next = (uint8_t *)malloc(newlen);
            size_t pos = 0;
            for (size_t i = 0; i < old; ++i) {
                uint8_t d = word[i];
                if (d == 0) {          /* 0 → 01 */
                    next[pos++] = 0;
                    next[pos++] = 1;
                } else if (d == 1) {   /* 1 → 02 */
                    next[pos++] = 0;
                    next[pos++] = 2;
                } else {               /* 2 → 0 */
                    next[pos++] = 0;
                }
            }
            free(word);
            word = next;
            len  = newlen;
        }
    }

    /* compute a(n) = Σ (digit + 1) over the first n digits */
    seq_t total = 0;
    for (idx_t i = 0; i < n; ++i)
        total += (seq_t)(word[i] + 1);

    return total;
}
